import{_ as t,o as a,c as r,a3 as n}from"./chunks/framework.DQ-7HQaQ.js";const m=JSON.parse('{"title":"Requirements and acceptance","description":"","frontmatter":{},"headers":[],"relativePath":"project/acceptance.md","filePath":"project/acceptance.md","lastUpdated":1794376220000}'),i={name:"project/acceptance.md"};function s(o,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="requirements-and-acceptance" tabindex="-1">Requirements and acceptance <a class="header-anchor" href="#requirements-and-acceptance" aria-label="Permalink to &quot;Requirements and acceptance&quot;">​</a></h1><p>Application scenarios below are <strong>planned, not yet verified in a runtime</strong>. The <a href="./../engineering/examples">documentation labs</a> cover selected rules only. Each future implementation issue must link actual evidence, not merely this page.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Requirement</th><th>Scenario</th></tr></thead><tbody><tr><td>R-01</td><td>Rust owns authoritative state; workers cannot bypass validation</td><td>A-01</td></tr><tr><td>R-02</td><td>Published claims resolve to immutable evidence or explicit derivation</td><td>A-02</td></tr><tr><td>R-03</td><td>Ambiguity remains unresolved; aliases are not globally unique</td><td>A-03</td></tr><tr><td>R-04</td><td>Merges/splits remain auditable and reversible</td><td>A-04</td></tr><tr><td>R-05</td><td>Draft/private content cannot leak into published retrieval or export</td><td>A-05</td></tr><tr><td>R-06</td><td>Repeated ingestion and result delivery do not duplicate acceptance</td><td>A-06</td></tr><tr><td>R-07</td><td>Exports are consistent, integrity-checked and portable</td><td>A-07</td></tr><tr><td>R-08</td><td>Missing capabilities degrade operations, not access to stored evidence</td><td>A-08</td></tr><tr><td>R-09</td><td>Streaming distinguishes completion, refusal, cancellation and interruption</td><td>A-09</td></tr><tr><td>R-10</td><td>Jobs recover without accepting expired or stale-attempt results</td><td>A-10</td></tr><tr><td>R-11</td><td>Answers preserve revision-pinned citations and session/library ownership</td><td>A-11</td></tr><tr><td>R-12</td><td>Public deployment is bounded and separate from authoring</td><td>A-12</td></tr><tr><td>R-13</td><td>Hosted releases follow tested twelve-factor boundaries; local exceptions are explicit</td><td>A-13</td></tr><tr><td>R-14</td><td>Publication binds approved content, base revision and actor within an atomic command</td><td>A-14</td></tr><tr><td>R-15</td><td>Reused source has immutable lineage, reviewed dependencies and reuse rights</td><td>A-15</td></tr></tbody></table><h2 id="acceptance-scenarios" tabindex="-1">Acceptance scenarios <a class="header-anchor" href="#acceptance-scenarios" aria-label="Permalink to &quot;Acceptance scenarios&quot;">​</a></h2><p><strong>A-01 · Worker boundary.</strong> Submit a wrong artifact hash, mismatched input receipt and proposal outside granted scope. None becomes canonical; rejection is auditable. Arbitrary paths and worker-supplied permissions are not authority.</p><p><strong>A-02 · Evidence integrity.</strong> Publish sourced and derived claims; resolve each to immutable inputs, typed spans and execution receipts. Reject dangling, tampered and inaccessible evidence. Keep a speaker&#39;s statement separate from a sensor measurement.</p><p><strong>A-03 · Identity traps.</strong> Two people share a name; an event has aliases; a vessel and incident share words. Preserve distinct identities and unresolved candidates. New evidence must not duplicate the canonical entity merely because a candidate hash changes.</p><p><strong>A-04 · Undo a bad merge.</strong> Merge and then split fixtures. Original mentions, prior decisions and revised assignments remain inspectable. Old published revisions and citations remain reproducible under retention policy.</p><p><strong>A-05 · Draft isolation.</strong> Put a unique fixture phrase in a draft/private source. Public lexical/vector/graph queries, answer text, caches, facets and edge endpoints must not disclose it. Inspect public export files, indexes and metadata—not just UI filters.</p><p><strong>A-06 · Retry.</strong> Import the same source version twice and deliver a task result twice. Accepted records remain stable; attempts remain visible. Reusing a request key with changed inputs produces conflict rather than accidental reuse.</p><p><strong>A-07 · Portable snapshot.</strong> Export during writes through a supported snapshot operation. Verify every referenced object, package version and migration compatibility. Open on another OS; missing/tampered objects fail explicitly. Import never starts bundled executables or external jobs automatically.</p><p><strong>A-08 · Missing worker/model.</strong> Open a Mac-created library on Linux. Existing evidence remains readable. Query embeddings require a compatible embedding space; unsupported generation is blocked with a reason. Deterministic mock output is visibly labelled and never masquerades as real inference.</p><p><strong>A-09 · Streaming faults.</strong> Split bytes/frames at every boundary, omit completion, send invalid provider outcomes, disconnect and cancel during blocked sends. Verify durable partial text, explicit terminal outcome and no silent paid restart through the real HTTPS proxy.</p><p><strong>A-10 · Crash recovery.</strong> Terminate workers/API/store at controlled boundaries. Reclaim expired leases, then deliver an old result from the same worker name. Reject stale epochs and deadline-expired results even before reclamation. Bound retries and queues; disk-full is not success.</p><p><strong>A-11 · Revision and session.</strong> Publish a newer library while a conversation exists; old citations open their original evidence. Switch accounts/tabs/views during a stream. Authorize every replay/evidence request before exposing identifiers or payloads. Retention gaps trigger scoped resynchronization.</p><p><strong>A-12 · Hosted limits.</strong> Public sessions cannot ingest, install workers, run commands or approve drafts. Enforce resource/output quotas and test restricted admin operations. Demonstrate restore and rollback with disposable data before production.</p><p><strong>A-13 · Operational profile.</strong> Execute TF-01–TF-12 from the <a href="./../engineering/twelve-factor">factor matrix</a>. Replace the API with empty local storage while retaining backing services. Promote the same tested artifact with changed deployment config. Document the local embedded-store exception rather than calling it stateless.</p><p><strong>A-14 · Publication transaction.</strong> Require an authenticated approver, exact proposal digest and expected revision. Tamper with the proposal, change the base, hide an endpoint and inject faults between write categories. Either all accepted records/review/event/revision commit or none do. No implicit endpoint promotion can bypass the review.</p><p><strong>A-15 · Reuse review.</strong> For each imported module, record pinned source and blob, symbols/callers, applicable notices, dependency boundary, characterization tests and intentional changes. Public CI must not need a private donor checkout, live credentials or private fixture data.</p><h2 id="evidence-levels" tabindex="-1">Evidence levels <a class="header-anchor" href="#evidence-levels" aria-label="Permalink to &quot;Evidence levels&quot;">​</a></h2><p>A static source observation, a synthetic lab pass, an application test pass, a browser check and a production observation are separate claims. Record platform/tool versions, fixture revision, command, expected/observed result and limitations. Do not turn historical donor test names into current pass counts.</p><p>Quality evaluation tracks false merges, unresolved cases, evidence relevance, source independence, latency, recovery and memory. Choose numerical targets after a reproducible baseline; no universal confidence score or unmeasured capacity promise is asserted here.</p>',23)])])}const h=t(i,[["render",s]]);export{m as __pageData,h as default};
